        /**
         * The alarm quit of the EventJournalEntry
         */
        readonly quit?: boolean
        /**
         * The flags of the EventJournalAlarm
         * 
         * bitmask:
         *  * sigApi.SIG_CONST.ALARM_ENTRY_FLAG_HAS_USERDATA 0x1
         *  * sigApi.SIG_CONST.ALARM_ENTRY_FLAG_STATUSSUPPORT 0x2
         *  * sigApi.SIG_CONST.ALARM_ENTRY_FLAG_ACTIVE 0x4
         *  * sigApi.SIG_CONST.ALARM_ENTRY_FLAG_QUIT 0x8
         * 
         * Active flag represents state active/inactive independent of quit.
         * This information is required when state is 255 to distinguish
         * between active/quit and inactive/quit. In contrast to the property quit,
         * quit flag is a constant and reflects the value as reported by the dataservice.
         */
